import networkx as nx
G = nx.Graph()
for g in range(5):
    for i in range(3):
        G.add_node(f'{g}_{i}')
for g in range(5):
    for i in range(3):
        G.add_edge(f'{g}_{i}', f'{g}_{(i+1)%3}')
for g in range(4):
    for i in range(3):
        G.add_edge(f'{g}_{i}', f'{g+1}_{i}')
print(G.number_of_nodes(), G.number_of_edges())
print(nx.is_connected(G))
